import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int a = sc.nextInt();
        int b = sc.nextInt();

        int costAllSingle = n * a;
        int fullPassesCost = (n / m) * b;
        int remainingRides = n % m;
        int remainingCost = Math.min(remainingRides * a, b);
        int mixedCost = fullPassesCost + remainingCost;

        int result = Math.min(costAllSingle, mixedCost);
        System.out.println(result);
    }
}

